    "contentHtml": "\n            <div id=\"news-post-6ab4469d6c20d6.58308042\" data-insert-ads=\"article\" data-zaf-dynamic=\"article\" data-units-dynamic=\"article\" data-zaf-slot=\"true\">Blizzard has teased that increased weather effects are coming soon to the WoW: Forever Beta.<div class=\"quote-box exclude-units\" data-type=\"blizzard\" data-has-links=\"true\" data-has-source=\"true\" data-has-toggle=\"true\"><div class=\"quote-source\">Blizzard</div><div class=\"quote-header\"><a href=\"https://us.forums.blizzard.com/en/wow/t/2359491/1\" target=\"_blank\">View Original</a><a class=\"quote-toggle\" href=\"javascript:\" aria-label=\"Toggle quote visibility\"></a></div><div class=\"quote-body\" data-markup-content-target=\"1\">Coming soon to the Beta</div></div><div class=\"wh-center\" style=\"text-align: -webkit-center;\"><div class=\"wh-youtube exclude-units lazy-load-background\" style=\"aspect-ratio: 16 / 9; background: url(&quot;https://i.ytimg.com/vi/grhjK8xH3H4/sddefault.jpg&quot;); max-width: 800px;\"><a aria-label=\"Play\" class=\"wh-youtube-inner\" href=\"javascript:\" style=\"padding-top: 45%;\"><i class=\"fa fa-play-circle\"></i></a></div></div></div>\n            \n            <noscript>Blizzard has teased that increased weather effects are coming soon to the WoW: Forever Beta.<br /><br /><div class=\"quote-box\" data-type=\"blizzard\"><div class=\"quote-header\"></div><div class=\"quote-body\">Coming soon to the Beta<br /></div></div><br /><br /></noscript>            \n        ",
